bool read_unlock_or_restart(const ArtNode* n, uint64_t start_v) {
    std::atomic_thread_fence(std::memory_order_acquire);
    uint64_t cur = n->version_lock_obsolete.load(std::memory_order_relaxed);
    return (cur == start_v); // false if locked, bumped, or obsolete
}

void retire_old_node(ArtNode* old_node, EbrThreadState& ebr) {
    old_node->version_lock_obsolete.fetch_or(OBSOLETE_BIT, std::memory_order_release);
    ebr.limbo[ebr.current_epoch % 3].push_back(old_node);
    ebr.try_reclaim_oldest_epoch();
}
